103:     private static void EnrichModifyRequests(MechanicalPackingListDto dto, List<MechanicalPackingListDetailChange> requests, Dictionary<Guid, string> employeeNameMap)
104:     {
105:         // Include both MODIFY and Approved ADD (TargetDetailId set after approval in ApprovePendingDetailsAsync).
106:         // Group by TargetDetailId — same detail có thể có nhiều requests (Approved cũ + Pending mới).
107:         // Ưu tiên Pending trước, sau đó lấy request mới nhất theo CreatedDate.
108:         var modifyByDetailId = requests
109:             .Where(c => c.TargetDetailId.HasValue &&
110:                         (c.RequestType == ChangeRequestType.Modify ||
111:                          (c.RequestType == ChangeRequestType.Add && c.RequestStatus == ChangeRequestStatus.Approved)))
112:             .GroupBy(c => c.TargetDetailId!.Value)
113:             .ToDictionary(
114:                 g => g.Key,
115:                 g => g.OrderBy(c => c.RequestStatus == ChangeRequestStatus.Pending ? 0 : 1)
116:                        .ThenByDescending(c => c.CreatedDate)
117:                        .First());
118: 
119:         foreach (var detail in dto.Details)
120:         {
121:             if (!modifyByDetailId.TryGetValue(detail.Id, out var req)) continue;
122: 
123:             var isApproved = req.RequestStatus == ChangeRequestStatus.Approved;
124:             var isRejected = req.RequestStatus == ChangeRequestStatus.Rejected;
125:             var resolvedByDisplay = req.ResolvedById.HasValue && employeeNameMap.TryGetValue(req.ResolvedById.Value, out var name)
126:                 ? name : req.ResolvedByUser;
127: 
128:             // Approved ADD row: committed row, only show approval badge — no quantity delta
129:             if (req.RequestType == ChangeRequestType.Add)
130:             {
131:                 detail.IsApproved = isApproved;
132:                 detail.PendingChange = new PendingChangeDto
133:                 {
134:                     RequestId = req.Id,
135:                     RequestType = req.RequestType,
136:                     RequestStatus = req.RequestStatus,
137:                     ResolvedAt = req.ResolvedAt,
138:                     ResolvedByUser = resolvedByDisplay
139:                 };
140:                 continue;
141:             }
142: 
143:             // MODIFY request: show old → new delta
144:             var old = TryDeserializePendingAdjust(req.OldData);
145:             var nw = TryDeserializePendingAdjust(req.NewData);
146:             if (old == null || nw == null) continue;
147: 
148:             detail.IsModified = !isApproved && !isRejected;
149:             detail.IsApproved = isApproved;
150:             detail.IsRejected = isRejected;
151:             detail.PendingChange = new PendingChangeDto
152:             {
153:                 RequestId = req.Id,
154:                 RequestType = req.RequestType,
155:                 RequestStatus = req.RequestStatus,
156:                 QuantityOld = old.Quantity,
157:                 QuantityNew = nw.Quantity,
158:                 DesignWeightOld = old.DesignWeight,
159:                 DesignWeightNew = nw.DesignWeight,
160:                 ResolvedAt = req.ResolvedAt,
161:                 ResolvedByUser = resolvedByDisplay
162:             };
163:         }
164:     }
