210:             .Include(x => x.Details)
211:             .ToListAsync();
212: 
213:         // Loại bỏ các phiếu đóng kiện thành phẩm bị hủy (Cancelled)
214:         try
215:         {
216:             var cancelledResp = await _masterDataGrpcClient.GetWorkItemIdsByStatusAsync(
217:                 new GetWorkItemIdsByStatusRequest
218:                 {
219:                     CategoryCode = nameof(FinishedGoodsPacking),
220:                     StatusEnums = { (int)Shared.Enums.EWorkItemStatus.Cancelled }
221:                 });
222:             if (cancelledResp?.Success == true && cancelledResp.WorkItemIds.Count > 0)
223:             {
224:                 var cancelledSet = cancelledResp.WorkItemIds
225:                     .Where(idStr => Guid.TryParse(idStr, out _))
226:                     .Select(Guid.Parse)
227:                     .ToHashSet();
228: 
229:                 finishedGoodsPackings = finishedGoodsPackings
230:                     .Where(p => !cancelledSet.Contains(p.Id))
231:                     .ToList();
232:             }
233:         }
234:         catch (Exception ex)
235:         {
236:             _logger.Warning(ex, "Không thể lấy danh sách phiếu đóng kiện bị hủy để loại trừ khi Enrich");
237:         }
238: 
239:         var actualWeightByPlDetailId = finishedGoodsPackings
240:             .SelectMany(fp => fp.Details)
241:             .GroupBy(d => d.MechanicalPackingListDetailId)
242:             .ToDictionary(g => g.Key, g => g.Sum(d => d.ActualWeight));
243: 
244:         var packedQtyByPlDetailId = finishedGoodsPackings
245:             .SelectMany(fp => fp.Details)
246:             .GroupBy(d => d.MechanicalPackingListDetailId)
247:             .ToDictionary(g => g.Key, g => g.Sum(d => d.ActualQuantity));
248: 
249:         var receiptQtyByPlDetailId = new Dictionary<Guid, decimal>();
250:         var deliveryQtyByPlDetailId = new Dictionary<Guid, decimal>();
251: 
252:         if (finishedGoodsPackings.Count > 0)
253:         {
254:             var packingIdStrings = finishedGoodsPackings.Select(fp => fp.Id.ToString()).ToList();
255:             var grpcRequest = new GetFgrDetailSummariesRequest();
256:             grpcRequest.PackingIds.AddRange(packingIdStrings);
257:             var grpcResponse = await _erpGrpcClient.GetFinishedGoodsReceiptDetailSummariesAsync(grpcRequest);
258: 
259:             var packingById = finishedGoodsPackings.ToDictionary(fp => fp.Id);
260:             receiptQtyByPlDetailId = grpcResponse.Items
261:                 .Where(rd => Guid.TryParse(rd.FinishedGoodsPackingId, out _))
262:                 .Select(rd =>
263:                 {
264:                     var packingId = Guid.Parse(rd.FinishedGoodsPackingId);
265:                     packingById.TryGetValue(packingId, out var packing);
266:                     return packing?.Details ?? Enumerable.Empty<FinishedGoodsPackingDetail>();
267:                 })
268:                 .SelectMany(details => details)
269:                 .GroupBy(d => d.MechanicalPackingListDetailId)
270:                 .ToDictionary(g => g.Key, g => g.Sum(d => d.ActualQuantity));
271: 
272:             // Tính SiteDelivery cho từng chi tiết
273:             var receiptDetailIds = grpcResponse.Items
274:                 .Select(rd => Guid.TryParse(rd.Id, out var rid) ? rid : Guid.Empty)
275:                 .Where(rid => rid != Guid.Empty)
276:                 .ToList();
277: 
278:             if (receiptDetailIds.Count > 0)
279:             {
280:                 // SiteDeliveryDetail giờ trỏ tới kiện lớn (FinishedGoodsDeliveryPackingId) → bắc cầu qua
281:                 // FinishedGoodsDeliveryPackingDetail để lấy các FinishedGoodsReceiptDetailId đã giao công trình.
282:                 var deliveredPackingIds = await _unitOfWork.GetRepository<SiteDeliveryDetail>().Query()
283:                     .Select(d => d.FinishedGoodsDeliveryPackingId)
284:                     .Distinct()
285:                     .ToListAsync();
286: 
287:                 var deliveredReceiptDetailIds = deliveredPackingIds.Count == 0
288:                     ? new List<Guid>()
289:                     : await _unitOfWork.GetRepository<FinishedGoodsDeliveryPackingDetail>().Query()
290:                         .Where(d => deliveredPackingIds.Contains(d.FinishedGoodsDeliveryPackingId)
291:                                     && receiptDetailIds.Contains(d.FinishedGoodsReceiptDetailId))
292:                         .Select(d => d.FinishedGoodsReceiptDetailId)
293:                         .Distinct()
294:                         .ToListAsync();
295: 
296:                 if (deliveredReceiptDetailIds.Count > 0)
297:                 {
298:                     var packingIdToDetailIds = finishedGoodsPackings
299:                         .SelectMany(fp => fp.Details)
300:                         .GroupBy(d => d.FinishedGoodsPackingId)
301:                         .ToDictionary(g => g.Key, g => g.ToList());
302: 
303:                     var receiptDetailToPackingId = grpcResponse.Items
304:                         .Where(rd => Guid.TryParse(rd.Id, out _) && Guid.TryParse(rd.FinishedGoodsPackingId, out _))
305:                         .ToDictionary(rd => Guid.Parse(rd.Id), rd => Guid.Parse(rd.FinishedGoodsPackingId));
306: 
307:                     var deliveryEvents = deliveredReceiptDetailIds
308:                         .Where(rid => receiptDetailToPackingId.ContainsKey(rid))
309:                         .Select(rid => receiptDetailToPackingId[rid])
310:                         .SelectMany(pid => packingIdToDetailIds.GetValueOrDefault(pid) ?? Enumerable.Empty<FinishedGoodsPackingDetail>())
311:                         .GroupBy(d => d.MechanicalPackingListDetailId)
312:                         .ToDictionary(g => g.Key, g => g.Sum(d => d.ActualQuantity));
313: 
314:                     deliveryQtyByPlDetailId = deliveryEvents;
315:                 }
316:             }
317:         }
318: 
319:         foreach (var detail in dto.Details)
320:         {
321:             detail.ActualWeight = actualWeightByPlDetailId.GetValueOrDefault(detail.Id, 0m);
322:             detail.PackedQuantity = packedQtyByPlDetailId.GetValueOrDefault(detail.Id, 0m);
323:             detail.PackedStatus = ComputeDeliveryStatus(detail.PackedQuantity, detail.Quantity);
324: 
325:             detail.ReceiptQuantity = receiptQtyByPlDetailId.GetValueOrDefault(detail.Id, 0m);
326:             detail.ReceiptStatus = ComputeDeliveryStatus(detail.ReceiptQuantity, detail.Quantity);
327: 
328:             detail.SiteDeliveryQuantity = deliveryQtyByPlDetailId.GetValueOrDefault(detail.Id, 0m);
329:             detail.SiteDeliveryStatus = ComputeDeliveryStatus(detail.SiteDeliveryQuantity, detail.Quantity);
330:         }
331: 
332:         dto.SiteDeliveryStatus = ComputeOverallStatus(dto.Details.Select(d => d.SiteDeliveryStatus));
333:     }
