478:     private static EPackingReportStatus ComputeDeliveryStatus(decimal actual, decimal design) => actual switch
479:     {
480:         0 => EPackingReportStatus.Empty,
481:         _ when actual < design => EPackingReportStatus.Partial,
482:         _ => EPackingReportStatus.Full
483:     };
484: 
485:     private static EPackingReportStatus ComputeOverallStatus(IEnumerable<EPackingReportStatus> statuses)
486:     {
487:         var list = statuses.ToList();
488:         if (list.Count == 0) return EPackingReportStatus.Empty;
489:         if (list.All(s => s == EPackingReportStatus.Full)) return EPackingReportStatus.Full;
490:         if (list.All(s => s == EPackingReportStatus.Empty)) return EPackingReportStatus.Empty;
491:         return EPackingReportStatus.Partial;
492:     }
