using CogainSolution.Grpc.ErpInfo;
using CogainSolution.Grpc.HrInfo;
using CogainSolution.Grpc.MasterDataInfo;
using Contracts.Domain.Entities;
using Microsoft.EntityFrameworkCore;
using ServiceDesk.Data.Entities.PackingList;
using ServiceDesk.Data.Entities.Production;
using Shared.Dto.ServiceDesk.PackingList;
using Shared.Dto.ServiceDesk.Production;
using Shared.Enums;
using Infrastructure.Extensions;
using System.Text.Json;

namespace ServiceDesk.Services.Implement.PackingList.MechanicalPackingLists;

public partial class MechanicalPackingListService
{
    #region Enrichment (gRPC)

    protected override async Task BeforeReturnGetPagedAsync(PagedResult<MechanicalPackingListDto> result)
    {
        if (result.Data?.Any() == true)
        {
            var dtos = result.Data.ToList();
            await _masterDataGrpcClient.EnrichWorkItemsAsync(dtos, _logger);
            await EnrichProjectInfoAsync(dtos);
            await EnrichProductionOrderInfoAsync(dtos);
            await EnrichModelInfoAsync(dtos);
            await EnrichSiteDeliveryStatusAsync(dtos);
        }
    }

    protected override async Task BeforeReturnGetAllAsync(IEnumerable<MechanicalPackingListDto> dtos)
    {
        var list = dtos.ToList();
        if (list.Count > 0)
        {
            await _masterDataGrpcClient.EnrichWorkItemsAsync(list, _logger);
            await EnrichProjectInfoAsync(list);
            await EnrichProductionOrderInfoAsync(list);
            await EnrichModelInfoAsync(list);
            await EnrichSiteDeliveryStatusAsync(list);
        }
    }

    protected override async Task BeforeReturnGetByIdAsync(MechanicalPackingListDto dto)
    {
        if (dto == null) return;
        await _masterDataGrpcClient.EnrichWorkItemsAsync([dto], _logger);
        await EnrichProjectInfoAsync([dto]);
        await EnrichProductionOrderInfoAsync([dto]);
        await EnrichModelInfoAsync([dto]);
        await EnrichActualWeightAndReceiptQuantityAsync(dto);
        await EnrichPendingChangesAsync(dto);
    }

