{
    try
    {
        if (dtos == null || dtos.Count == 0) return;

        var poIds = dtos
            .Where(d => d.ProductionOrderId.HasValue && d.ProductionOrderId.Value != Guid.Empty)
            .Select(d => d.ProductionOrderId!.Value)
            .Distinct()
            .ToList();

        if (poIds.Count == 0) return;

        var poRepo = _unitOfWork.GetRepository<ProductionOrder>();
        var pos = await poRepo.Query(x => poIds.Contains(x.Id)).AsNoTracking().ToListAsync();
        var poMap = pos.ToDictionary(x => x.Id);

        foreach (var dto in dtos)
        {
            if (dto.ProductionOrderId.HasValue && poMap.TryGetValue(dto.ProductionOrderId.Value, out var po))
            {
                dto.ProductionOrder ??= _mapper.Map<ProductionOrderDto>(po);
                if (string.IsNullOrEmpty(dto.ProductionOrderCodeSnapshot))
                {
                    dto.ProductionOrderCodeSnapshot = po.Code;
                }
                if (string.IsNullOrEmpty(dto.ProductionOrderNameSnapshot))
                {
                    dto.ProductionOrderNameSnapshot = po.Name;
                }
            }
        }
    }
    catch (Exception ex)
