const productionOrderOptions = useMemo(() => {
  return (
    (productionOrdersQuery.data?.data as any[])?.map((po) => ({
      label: po.code ? `${po.code} - ${po.name}` : po.name || '',
      value: po.id ?? '',
    })) ?? []
  );
}, [productionOrdersQuery.data?.data]);

const productionOrderMap = useMemo(() => {
  const map = new Map<string, { code?: string; name?: string }>();
  const pos = (productionOrdersQuery.data?.data as any[]) || [];
  pos.forEach((po) => {
    if (po.id) {
      map.set(po.id, { code: po.code, name: po.name });
    }
  });
  return map;
}, [productionOrdersQuery.data?.data]);

