                      {t('dialogs.add.validation.projectRequired')}
                    </p>
                  )}
                </div>

                {/* Mã thành phẩm (readonly, auto-filled) */}
                <div className="flex flex-col gap-1.5">
                  <FormLabel className="text-sm font-medium">
                    {t('dialogs.add.finishedGoodCodeLabel')}
                  </FormLabel>
                  <Input
                    value={displayFinishedGoodCode}
                    readOnly
                    disabled
                    placeholder={t('dialogs.add.finishedGoodCodePlaceholder')}
                    className="bg-muted text-muted-foreground h-9"
                  />
                </div>

                {/* Model hiệu suất (readonly) */}
                <div className="flex flex-col gap-1.5">
                  <FormLabel className="text-sm font-medium">
                    {t('dialogs.add.performanceModelLabel')}
                  </FormLabel>
                  <Input
                    value={displayPerformanceModel}
                    readOnly
                    disabled
                    className="bg-muted text-muted-foreground h-9"
                  />
                </div>

                {/* Model thiết kế (readonly) */}
                <div className="flex flex-col gap-1.5">
                  <FormLabel className="text-sm font-medium">
                    {t('dialogs.add.designModelLabel')}
                  </FormLabel>
                  <Input
                    value={displayDesignModel}
                    readOnly
                    disabled
                    className="bg-muted text-muted-foreground h-9"
                  />
                </div>

                {/* Kích thước */}
                <div className="flex flex-col gap-1.5">
                  <FormLabel className="text-sm font-medium">
                    {t('dialogs.add.dimensionsLabel')}
                    <span className="text-destructive"> *</span>
                  </FormLabel>
                  <div className="flex items-center gap-1">
                    <FormField
                      control={form.control}
                      name="dimensionL"
                      render={({ field }) => (
                        <FormItem className="flex-1 space-y-0">
                          <FormControl>
                            <NumericInput
                              className="text-center h-9"
                              placeholder={t('dialogs.add.dimensionLPlaceholder')}
                              disabled={!isIndependent && !selectedMechId}
                              value={field.value}
                              onValueChange={(val) => field.onChange(val ?? 0)}
                            />
                          </FormControl>
                        </FormItem>
                      )}
                    />
                    <span className="text-muted-foreground text-sm shrink-0">x</span>
                    <FormField
                      control={form.control}
                      name="dimensionW"
                      render={({ field }) => (
                        <FormItem className="flex-1 space-y-0">
                          <FormControl>
                            <NumericInput
                              className="text-center h-9"
                              placeholder={t('dialogs.add.dimensionWPlaceholder')}
                              disabled={!isIndependent && !selectedMechId}
                              value={field.value}
                              onValueChange={(val) => field.onChange(val ?? 0)}
                            />
                          </FormControl>
                        </FormItem>
                      )}
                    />
                    <span className="text-muted-foreground text-sm shrink-0">x</span>
                    <FormField
                      control={form.control}
                      name="dimensionH"
                      render={({ field }) => (
                        <FormItem className="flex-1 space-y-0">
                          <FormControl>
                            <NumericInput
                              className="text-center h-9"
                              placeholder={t('dialogs.add.dimensionHPlaceholder')}
                              disabled={!isIndependent && !selectedMechId}
                              value={field.value}
                              onValueChange={(val) => field.onChange(val ?? 0)}
                            />
                          </FormControl>
                        </FormItem>
                      )}
                    />
                  </div>
                  {(form.formState.errors.dimensionL ||
                    form.formState.errors.dimensionW ||
                    form.formState.errors.dimensionH) && (
                    <p className="text-xs text-destructive">
                      {t('dialogs.add.validation.dimensionRequired', {
                        defaultValue: 'Nhập kích thước > 0',
                      })}
                    </p>
                  )}
                </div>

content:
Nguyên nhân khiến bạn đã nhập kích thước > 0 nhưng form vẫn báo lỗi **"Nhập kích thước > 0"**:

---

### 1. Nguyên nhân gốc rễ (Root Causes)

1. **Lệch kiểu dữ liệu giữa `NumericInput` và Zod schema (`Expected string, received number`):**
   - Component `<NumericInput />` gọi sự kiện `onValueChange={(val) => field.onChange(val ?? 0)}`, truyền vào form giá trị là một **`number`** (ví dụ: `1200`).
   - Nhưng trong schema Zod, trường lại khai báo là `dimensionL: z.string().optional().refine(...)`.
   - Khi Zod validate một giá trị số `1200` vào `z.string()`, nó bị **lỗi kiểu dữ liệu** ngay lập tức (`Expected string, received number`) và không bao giờ chạy đến hàm `.refine()` kiểm tra `> 0`.
   - Tại vị trí hiển thị lỗi ở UI trước đó lại viết:
     ```tsx
     {(form.formState.errors.dimensionL ||
       form.formState.errors.dimensionW ||
       form.formState.errors.dimensionH) && (
       <p className="text-xs text-destructive">
         {t('dialogs.add.validation.dimensionRequired', {
           defaultValue: 'Nhập kích thước > 0',
         })}
       </p>
     )}
     ```
     Bởi vì `errors.dimensionL` tồn tại (với lỗi `Expected string, received number`), UI vẫn hiển thị dòng chữ fallback cứng: **"Nhập kích thước > 0"**, làm người dùng tưởng rằng giá trị mình nhập vẫn bị coi là `<= 0`.

2. **Gộp chung 1 thông báo lỗi cho cả 3 ô (Dài x Rộng x Cao):**
   - Kích thước gồm 3 trường: `dimensionL`, `dimensionW`, `dimensionH`.
   - Nếu bạn mới nhập Chiều dài (`dimensionL`), nhưng Chiều rộng (`dimensionW`) hoặc Chiều cao (`dimensionH`) vẫn đang rỗng `""`, thì `Number("") > 0` sẽ trả về `false`.
   - Khi đó `errors.dimensionW` hoặc `errors.dimensionH` bị lỗi, và UI lại hiện dòng chung chung **"Nhập kích thước > 0"**, gây hiểu lầm là ô vừa nhập bị lỗi.

---

### 2. Các thay đổi đã xử lý

1. **Cho phép cả `string` lẫn `number` trong schema ([`finished-goods-packing-form.tsx`](file:///c:/Users/Admin/Desktop/CogainCore/cogain-core/frontend/bizdoc/src/routes/_app/logistic/finished-goods-packing/_components/finished-goods-packing-form.tsx)):**
   - Dùng `z.union([z.string(), z.number()])` để dù `NumericInput` trả về `number` hay `string` thì đều kiểm tra `Number(v) > 0` một cách chính xác.
   - Thêm thông báo lỗi chi tiết theo từng chiều (Chiều dài, Chiều rộng, Chiều cao):
     ```tsx
     dimensionL: z
       .union([z.string(), z.number()])
       .refine((v) => {
         if (v === '' || v === null || v === undefined) return false;
         const num = typeof v === 'number' ? v : Number(v);
         return !Number.isNaN(num) && num > 0;
       }, {
         message: t('dialogs.add.validation.dimensionLRequired', {
           defaultValue: 'Nhập chiều dài > 0',
         }),
       }),
     // Tương tự cho dimensionW và dimensionH
     ```

2. **Cập nhật `NumericInput` `onValueChange` & hiển thị lỗi chi tiết:**
   - Cập nhật `onValueChange={(val) => field.onChange(val !== undefined && val !== null ? val : '')}`.
   - Khi có lỗi ở ô nào, ô đó sẽ viền đỏ cảnh báo (`border-destructive focus-visible:ring-destructive`).
   - Hiển thị chính xác thông báo lỗi của ô đang thiếu (ví dụ: *"Nhập chiều rộng > 0"*, *"Nhập chiều cao > 0"*).

3. **Bổ sung từ khóa i18n vào từ điển:**
   - Đã thêm `dimensionLRequired`, `dimensionWRequired`, `dimensionHRequired` vào cả [`vi/finished-goods-packing.json`](file:///c:/Users/Admin/Desktop/CogainCore/cogain-core/frontend/bizdoc/src/locales/vi/finished-goods-packing.json) và [`en/finished-goods-packing.json`](file:///c:/Users/Admin/Desktop/CogainCore/cogain-core/frontend/bizdoc/src/locales/en/finished-goods-packing.json).
